-- ML-DSA keys as xca#51 stored them (BTD-194): the private part is the
-- PKCS#8 that the default OpenSSL context writes, encrypted with the
-- fixture database password. Made once in the build image (OpenSSL 4.1.0)
--   openssl genpkey -algorithm ML-DSA-44 -provparam
--     ml-dsa.output_formats=<f> -out fixture51-<f>.pem
--     for f = seed-priv, seed-only, priv-only
--   xca --no-gui --import fixture51-<f>.pem (fork 1f7560f6)
--   private_keys.private replaced by base64 of
--     openssl pkcs8 -topk8 -v2 aes-256-cbc -v2prf hmacWithSHA256
--     -passout pass:service-test-db-pass -outform DER
--   (what i2d_PKCS8PrivateKey_bio with EVP_aes_256_cbc wrote in #51)
-- then dumped with the sqlite3 module of python3
BEGIN TRANSACTION;
CREATE TABLE audit_keys (key_id CHAR(64) PRIMARY KEY, created VARCHAR(32), key_type VARCHAR(16), public_key TEXT, private TEXT, retired SMALLINT NOT NULL DEFAULT 0);
CREATE TABLE audit_log (seq INTEGER PRIMARY KEY, created VARCHAR(32), actor VARCHAR(256), channel VARCHAR(8), action VARCHAR(64), object_type VARCHAR(32), object_id VARCHAR(128), params TEXT, result VARCHAR(16), error_code VARCHAR(64), prev_hash CHAR(64), hash CHAR(64));
